import json
from collections import Counter

def components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and (i,j) not in seen:
                stack=[(i,j)]; comp=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<h and 0<=y<w and grid[x][y]!=bg and (x,y) not in seen:
                            stack.append((x,y))
                comps.append(comp)
    return comps

def complete_partial(grid):
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    comps=sorted(components(grid,bg),key=len,reverse=True)
    full,part=comps[0],comps[1]
    fs=set(full)
    # find translation mapping part into full
    cands=None
    for (pi,pj) in part:
        opts={(fi-pi,fj-pj) for (fi,fj) in fs}
        cands = opts if cands is None else cands&opts
        if not cands: break
    t=cands.pop()
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    for (fi,fj) in full:
        x,y=fi+t[0],fj+t[1]
        if 0<=x<h and 0<=y<w and out[x][y]==bg:
            out[x][y]=1
    return out

def f(grid): return complete_partial(grid)
