def bands(grid,bg):
    rows=[i for i,r in enumerate(grid) if any(v!=bg for v in r)]
    bs=[]; 
    for i in rows:
        if bs and i==bs[-1][-1]+1: bs[-1].append(i)
        else: bs.append([i])
    return [{(i,j) for i in b for j,v in enumerate(grid[i]) if v!=bg} for b in bs]

def solve(grid):
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    bs=bands(grid,bg)
    h,w=len(grid),len(grid[0])
    bestscore,best=-1,None
    for A in bs:
        for B in bs:
            if A is B: continue
            for (pi,pj) in B:
                for (fi,fj) in A:
                    t=(fi-pi,fj-pj)
                    sc=sum(1 for p in B if (p[0]+t[0],p[1]+t[1]) in A)
                    if sc>bestscore: bestscore,best=sc,(A,B,t)
    A,B,t=best; s=(-t[0],-t[1])
    out=[r[:] for r in grid]
    for (fi,fj) in A:
        x,y=fi+s[0],fj+s[1]
        if 0<=x<h and 0<=y<w and out[x][y]==bg: out[x][y]=1
    return out,(bestscore,best[2],s)

